package com.example.demo.service;
import org.springframework.stereotype.Service;
import java.util.*;
@Service
public class StorePolicyService {
 public record Policy(String id,String title,String text) implements java.io.Serializable {}
 public List<Policy> policies(){return List.of(
  new Policy("returns","Đổi trả và hoàn tiền","Chủ đơn đã hoàn thành có thể gửi một yêu cầu trong 24 giờ từ thời điểm bàn giao, kèm mô tả 20–2.000 ký tự và 1–3 ảnh JPG/PNG (mỗi ảnh tối đa 5 MB). Cửa hàng kiểm tra lỗi hư hỏng, sai bánh, thiếu bánh hoặc sai mẫu đã duyệt; gửi yêu cầu không đồng nghĩa được duyệt. Thay đổi sở thích không tự động đủ điều kiện đổi trả. Admin duyệt đổi bánh/làm lại hoặc hoàn một phần/toàn bộ, hoặc từ chối có lý do. Đơn cũ chưa có giờ bàn giao hay quá hạn có thể gửi phiếu hỗ trợ để xem xét riêng. Không tự nhập lại bánh thực phẩm bị trả vào kho bán. Duyệt hoàn chưa có nghĩa đã chuyển tiền; chỉ ghi nhận khoản thực trả, không vượt số được duyệt và tiền cửa hàng còn giữ."),
  new Policy("voucher","Mã giảm giá","Mỗi đơn dùng tối đa một mã, không cộng gộp mã. Phải còn thời hạn, đang bật, đủ tiền bánh tối thiểu, còn tổng lượt và lượt mỗi người. Phụ kiện và phí giao hàng không được giảm, không tính vào điều kiện tiền bánh. Có thể hưởng cùng miễn phí giao hàng nếu đủ ngưỡng. Mã phần trăm có thể bị giới hạn mức giảm. Xem trước không giữ lượt; kiểm tra lại khi đặt. Hủy đơn không hoàn lượt mã."),
  new Policy("delivery","Giao nhận và thanh toán","Phí giao hàng 30.000 đ; miễn phí khi tiền bánh từ 500.000 đ trước giảm giá, không tính phụ kiện. Nhận tại cửa hàng miễn phí giao, yêu cầu cọc 50% hoặc trả đủ bằng chuyển khoản, đối soát đủ khoản trả trước rồi mới xác nhận/làm. Đặt đơn không đồng nghĩa đã nhận tiền. Đơn thường chọn từ ngày mai đến 30 ngày, bật đặt trước đến 90 ngày; các giờ 09:00–12:00, 13:00–17:00, 18:00–20:00. Bánh riêng cần đặt trước 3–90 ngày, chốt báo giá và duyệt mẫu mới nhất trước khi làm. QR nhận bánh dùng để tra đơn, chỉ bàn giao khi sẵn sàng và đã trả đủ."),
  new Policy("cancel","Hủy đơn","Chủ đơn hoặc admin chỉ hủy đơn thường khi chờ xác nhận. Hủy hoàn kho bánh/phụ kiện nhưng không hoàn lượt voucher, không tự chuyển tiền hoàn. Các trạng thái sau cần gửi phiếu hỗ trợ. Bánh riêng có thể tự hủy khi chờ/đã báo giá; sau khi chốt cần trao đổi với cửa hàng."),
  new Policy("care","Thành phần, dị ứng và bảo quản","Chỉ dùng thành phần, thông tin dị ứng và hướng dẫn bảo quản được cửa hàng nhập cho từng sản phẩm. Dữ liệu trống không đồng nghĩa an toàn, không có chất gây dị ứng hoặc bảo quản được ở nhiệt độ phòng. Nếu chưa rõ, hãy hỏi nhân viên trước khi đặt. Trợ lý không chẩn đoán, không xác nhận an toàn y tế và không suy đoán công thức."),
  new Policy("assistant","Nguồn và phạm vi trợ lý","Trợ lý dùng danh mục công khai, giá, tồn kho và nội dung sản phẩm đang bán, cùng các chính sách trên trang này. Mỗi trả lời có liên kết nguồn và thời điểm đọc. Không tra dữ liệu người mua khác, không thay đổi đơn, thu tiền hay tự hứa hoàn tiền. Hội thoại gần đây lưu trong phiên đăng nhập; chỉ chuyển cho nhân viên khi khách chủ động tạo phiếu và chọn chia sẻ. Câu hỏi ngoài mua bánh/chính sách sẽ được giới hạn phạm vi. Phiếu hỗ trợ là hộp thư trên website, không cam kết có nhân viên trực tuyến ngay.")
 );}
 public Policy policy(String id){return policies().stream().filter(p->p.id().equals(id)).findFirst().orElseThrow();}
}
